<script setup>defineProps({title:String,message:String,tone:{type:String,default:'neutral'},loading:Boolean})</script><template><section class="lp-card flex min-h-48 flex-col items-center justify-center p-7 text-center md:p-10" :aria-busy="loading"><span v-if="loading" class="lp-spinner mb-4 text-indigo" aria-hidden="true"></span><div v-else :class="['mb-4 h-2 w-12 rounded-full',tone==='error'?'bg-red-700':tone==='success'?'bg-emerald-700':tone==='warning'?'bg-amber-600':'bg-indigo']"></div><h3 class="text-xl font-bold">{{title}}</h3><p class="mt-2 max-w-md text-sm leading-6 text-slate-600">{{message}}</p><slot/></section></template>
